head.script:
scwin.createWindowTest = function(title, id) {
    wc1.createWindow(title, "", "/websquare5_sp2/sample/gridView/gridView_selectBox_linkedDataList.xml", "windowTitle", id, "newWindow", null, null, null, null, "wframe");
};
scwin.button1_onclick = function(e) {
    scwin.createWindowTest("aaa", "windowId0");
    scwin.createWindowTest("aaa", "windowId1");
    scwin.createWindowTest("aaa", "windowId2");
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wc1_windowList').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wc1_windows_list').children[1].children[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wc1_nameLayer_'+$p.id+'wc1_subWindow1').hasClass('w2windowContainer_selectedNameLayer')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
